	/** Checks the binding facts without requiring the same lexical scope identity. */
	public boolean bindingFactsEquivalent(Set<String> names, ReadOnlyContext left, ReadOnlyContext right) {
		for (String name : names) {
			if (left.visibleNames.contains(name) != right.visibleNames.contains(name)
					|| left.maybeBoundNames.contains(name) != right.maybeBoundNames.contains(name)
					|| left.guaranteedNames.contains(name) != right.guaranteedNames.contains(name)
					|| !Objects.equals(left.fixedValues.get(name), right.fixedValues.get(name))
					|| !left.valueKinds.getOrDefault(name, Set.of())
							.equals(right.valueKinds.getOrDefault(name, Set.of()))) {
				return false;
			}
		}
		return true;
	}

	/** Computes the evaluator input of a new, unmarked Join replacing the given node. */
	public ReadOnlyContext contextForInsertedJoin(TupleExpr replacedNode) {
		QueryModelNode parent = replacedNode.getParentNode();
		if (parent == null) {
			return contextAt(replacedNode);
		}

		ReadOnlyContext parentInput = contextAt(parent);
		if (parent instanceof Join join && replacedNode == join.getRightArg()) {
			return parentInput.withOutput(outputFacts(join.getLeftArg(), parentInput));
		}
		return childInput(parent, replacedNode, parentInput);
	}

